     6→export interface RecordingOptions {
     7→  fps: number;
     8→  duration: number; // in seconds
     9→  quality: number; // 0.0 to 1.0
    10→  format: "png" | "jpg";
    11→}
    12→
    13→export interface FrameData {
    14→  uri: string;
    15→  timestamp: number;
    16→  index: number;
    17→}
    18→
    19→export class VideoRecordingService {
    20→  private frames: FrameData[] = [];
    21→  private isRecording = false;
    22→  private recordingOptions: RecordingOptions;
    23→
    24→  constructor(options: Partial<RecordingOptions> = {}) {
    25→    this.recordingOptions = {
    26→      fps: 30,
    27→      duration: 10,
    28→      quality: 0.8,
    29→      format: "png",
    30→      ...options,
    31→    };
    32→  }
    33→
    34→  async startRecording(): Promise<void> {
    35→    if (this.isRecording) {
    36→      throw new Error("Recording already in progress");
    37→    }
    38→
    39→    this.isRecording = true;
    40→    this.frames = [];
    41→    console.log("Recording started");
    42→  }
    43→
    44→  async captureFrame(viewRef: any, frameIndex: number): Promise<void> {
    45→    if (!this.isRecording) return;
    46→
    47→    try {
    48→      const uri = await captureRef(viewRef, {
    49→        format: this.recordingOptions.format,
    50→        quality: this.recordingOptions.quality,
    51→        result: "tmpfile",
    52→      });
    53→
    54→      const frameData: FrameData = {
    55→        uri,
    56→        timestamp: Date.now(),
    57→        index: frameIndex,
    58→      };
    59→
    60→      this.frames.push(frameData);
    61→      console.log(`Captured frame ${frameIndex + 1}`);
    62→    } catch (error) {
    63→      console.error("Frame capture failed:", error);
    64→      throw error;
    65→    }
    66→  }
    67→
    68→  async stopRecording(): Promise<FrameData[]> {
    69→    this.isRecording = false;
    70→    console.log(`Recording stopped. Captured ${this.frames.length} frames`);
    71→    return [...this.frames];
    72→  }
    73→
    74→  async createVideoFromFrames(frames: FrameData[]): Promise<string> {
    75→    // For Expo managed workflow, this would typically require:
    76→    // 1. Server-side processing with FFmpeg
    77→    // 2. Or using a third-party service
    78→    // 3. Or creating a GIF from frames (simpler alternative)
    79→
    80→    // Simplified implementation: Create a GIF-like sequence
    81→    const videoDirectory = FileSystem.documentDirectory + "videos/";
    82→
    83→    // Ensure directory exists
    84→    const dirInfo = await FileSystem.getInfoAsync(videoDirectory);
    85→    if (!dirInfo.exists) {
    86→      await FileSystem.makeDirectoryAsync(videoDirectory, {
    87→        intermediates: true,
    88→      });
    89→    }
    90→
    91→    // For now, create a placeholder image if there are no frames
    92→    const videoFileName = `route_video_${Date.now()}.png`;
    93→    const videoPath = videoDirectory + videoFileName;
    94→
    95→    if (frames.length > 0) {
    96→      // Copy first frame as placeholder
    97→      await FileSystem.copyAsync({
    98→        from: frames[0].uri,
    99→        to: videoPath,
   100→      });
   101→    } else {
   102→      // Create a placeholder file for demo purposes
   103→      const placeholderText =
   104→        "This is a placeholder for video recording.\n" +
   105→        "In a production app, this would be an actual video file.\n" +
   106→        "Timestamp: " +
   107→        new Date().toISOString();
   108→
   109→      await FileSystem.writeAsStringAsync(videoPath, placeholderText);
   110→    }
   111→
   112→    return videoPath;
   113→  }
   114→
   115→  async cleanupFrames(frames: FrameData[]): Promise<void> {
   116→    try {
   117→      await Promise.all(
   118→        frames.map((frame) =>
   119→          FileSystem.deleteAsync(frame.uri, { idempotent: true })
   120→        )
   121→      );
   122→      console.log("Cleaned up temporary frame files");
   123→    } catch (error) {
   124→      console.warn("Frame cleanup failed:", error);
   125→    }
   126→  }
   127→
   128→  getRecordingStats() {
   129→    return {
   130→      frameCount: this.frames.length,
   131→      isRecording: this.isRecording,
   132→      estimatedDuration: this.frames.length / this.recordingOptions.fps,
   133→    };
   134→  }
   135→}
