     1→import * as MediaLibrary from 'expo-media-library';
     2→import * as FileSystem from 'expo-file-system';
     3→import * as Sharing from 'expo-sharing';
     4→import { Platform, Alert, Linking } from 'react-native';
     5→
     6→export class VideoExportService {
     7→  async requestPermissions(): Promise<boolean> {
     8→    try {
     9→      const { status } = await MediaLibrary.requestPermissionsAsync();
    10→      return status === 'granted';
    11→    } catch (error) {
    12→      console.error('Permission request failed:', error);
    13→      return false;
    14→    }
    15→  }
    16→
    17→  async saveVideoToGallery(videoUri: string, albumName: string = 'Travel Routes'): Promise<MediaLibrary.Asset> {
    18→    try {
    19→      // Check permissions
    20→      const hasPermissions = await this.requestPermissions();
    21→      if (!hasPermissions) {
    22→        throw new Error('Media library permissions not granted');
    23→      }
    24→
    25→      // Download if remote URL
    26→      let localUri = videoUri;
    27→      if (videoUri.startsWith('http')) {
    28→        const filename = `video_${Date.now()}.mp4`;
    29→        const downloadResult = await FileSystem.downloadAsync(
    30→          videoUri,
    31→          FileSystem.documentDirectory + filename
    32→        );
    33→        localUri = downloadResult.uri;
    34→      }
    35→
    36→      // Create asset in media library
    37→      const asset = await MediaLibrary.createAssetAsync(localUri);
    38→
    39→      // Create or get album
    40→      let album = await MediaLibrary.getAlbumAsync(albumName);
    41→      if (album == null) {
    42→        await MediaLibrary.createAlbumAsync(albumName, asset, false);
    43→      } else {
    44→        await MediaLibrary.addAssetsToAlbumAsync([asset], album, false);
    45→      }
    46→
    47→      return asset;
    48→    } catch (error) {
    49→      console.error('Error saving video:', error);
    50→      throw error;
    51→    }
    52→  }
    53→
    54→  async shareVideo(videoUri: string): Promise<void> {
    55→    try {
    56→      const isAvailable = await Sharing.isAvailableAsync();
    57→      if (!isAvailable) {
    58→        throw new Error('Sharing not available on this device');
    59→      }
    60→
    61→      await Sharing.shareAsync(videoUri, {
    62→        mimeType: 'video/mp4',
    63→        dialogTitle: 'Share Route Video',
    64→        UTI: 'public.movie'
    65→      });
    66→    } catch (error) {
    67→      console.error('Sharing failed:', error);
    68→      throw error;
    69→    }
    70→  }
    71→
    72→  async getStorageInfo() {
    73→    try {
    74→      const totalSpace = await FileSystem.getTotalDiskCapacityAsync();
    75→      const freeSpace = await FileSystem.getFreeDiskStorageAsync();
    76→
    77→      return {
    78→        totalSpace: Math.round(totalSpace / (1024 * 1024 * 1024)), // GB
    79→        freeSpace: Math.round(freeSpace / (1024 * 1024 * 1024)), // GB
    80→        usedPercentage: Math.round(((totalSpace - freeSpace) / totalSpace) * 100)
    81→      };
    82→    } catch (error) {
    83→      console.error('Storage info failed:', error);
    84→      return null;
    85→    }
    86→  }
    87→
    88→  handleError(error: Error, operation: string = 'video export') {
    89→    let userMessage = `Failed to ${operation}. `;
    90→    let actionRequired = false;
    91→
    92→    if (error.message.includes('permission')) {
    93→      userMessage += 'Please grant media library permissions in settings.';
    94→      actionRequired = true;
    95→    } else if (error.message.includes('storage')) {
    96→      userMessage += 'Not enough storage space available.';
    97→    } else if (error.message.includes('network')) {
    98→      userMessage += 'Please check your internet connection.';
    99→    } else {
   100→      userMessage += 'Please try again.';
   101→    }
   102→
   103→    const buttons = [{ text: 'OK', style: 'default' as const }];
   104→
   105→    if (actionRequired) {
   106→      buttons.unshift({
   107→        text: 'Open Settings',
   108→        onPress: () => Linking.openSettings()
   109→      } as const);
   110→    }
   111→
   112→    Alert.alert('Error', userMessage, buttons);
   113→  }
   114→}
