     4→
     5→export interface FrameCaptureOptions {
     6→  fps: number;
     7→  quality: number; // 0.0 to 1.0
     8→  format: "png" | "jpg";
     9→  width?: number;
    10→  height?: number;
    11→}
    12→
    13→export interface CapturedFrame {
    14→  uri: string;
    15→  index: number;
    16→  timestamp: number;
    17→}
    18→
    19→export interface FrameCaptureProgress {
    20→  total: number;
    21→  current: number;
    22→  percentage: number;
    23→}
    24→
    25→export interface FrameCaptureState {
    26→  isCapturing: boolean;
    27→  capturedFrames: CapturedFrame[];
    28→  progress: FrameCaptureProgress;
    29→  error: string | null;
    30→  tempDirectory: string | null;
    31→}
    32→
    33→export interface FrameCaptureActions {
    34→  startCapture: (options?: Partial<FrameCaptureOptions>) => Promise<void>;
    35→  captureFrame: (
    36→    viewRef: any,
    37→    index: number,
    38→    totalFrames: number
    39→  ) => Promise<CapturedFrame | null>;
    40→  stopCapture: () => Promise<CapturedFrame[]>;
    41→  cleanupFrames: () => Promise<void>;
    42→  exportFrameDirectory: () => Promise<string | null>;
    43→  getFrameFilesInfo: () => {
    44→    count: number;
    45→    directory: string;
    46→    isCapturing: boolean;
    47→  };
    48→}
    49→
    50→export interface UseFrameCaptureReturn
    51→  extends FrameCaptureState,
    52→    FrameCaptureActions {
    53→  setProgressCallback: (
    54→    callback: (progress: FrameCaptureProgress) => void
    55→  ) => void;
    56→  updateOptions: (newOptions: Partial<FrameCaptureOptions>) => void;
    57→}
    58→
    59→// Default options for frame capture
    60→const DEFAULT_FRAME_CAPTURE_OPTIONS: FrameCaptureOptions = {
    61→  fps: 30,
    62→  quality: 1.0,
    63→  format: "png",
    64→  width: 1024,
    65→  height: 1024,
    66→};
    67→
    68→/**
    69→ * Custom hook for frame capture functionality
    70→ * Follows React Native guidelines with functional approach
    71→ */
    72→export const useFrameCapture = (
    73→  initialOptions?: Partial<FrameCaptureOptions>
    74→): UseFrameCaptureReturn => {
    75→  // State management using React hooks
    76→  const [state, setState] = useState<FrameCaptureState>({
    77→    isCapturing: false,
    78→    capturedFrames: [],
    79→    progress: { total: 0, current: 0, percentage: 0 },
    80→    error: null,
    81→    tempDirectory: null,
    82→  });
    83→
    84→  // Refs for mutable values that don't trigger re-renders
    85→  const optionsRef = useRef<FrameCaptureOptions>({
    86→    ...DEFAULT_FRAME_CAPTURE_OPTIONS,
    87→    ...initialOptions,
    88→  });
    89→  const onProgressCallbackRef = useRef<
    90→    ((progress: FrameCaptureProgress) => void) | null
    91→  >(null);
    92→
    93→  // Update options
    94→  const updateOptions = useCallback(
    95→    (newOptions: Partial<FrameCaptureOptions>) => {
    96→      optionsRef.current = { ...optionsRef.current, ...newOptions };
    97→    },
    98→    []
    99→  );
   100→
   101→  // Set progress callback
   102→  const setProgressCallback = useCallback(
   103→    (callback: (progress: FrameCaptureProgress) => void) => {
   104→      onProgressCallbackRef.current = callback;
   105→    },
   106→    []
   107→  );
   108→
   109→  // Initialize frame capture
   110→  const initialize = useCallback(async (): Promise<void> => {
   111→    const tempDirectory = `${
   112→      FileSystem.cacheDirectory
   113→    }frame_capture_${Date.now()}/`;
   114→
   115→    try {
   116→      const dirInfo = await FileSystem.getInfoAsync(tempDirectory);
   117→      if (!dirInfo.exists) {
   118→        await FileSystem.makeDirectoryAsync(tempDirectory, {
   119→          intermediates: true,
   120→        });
   121→      }
   122→
   123→      setState((prev) => ({
   124→        ...prev,
   125→        tempDirectory,
   126→        capturedFrames: [],
   127→        error: null,
   128→      }));
   129→    } catch (error) {
   130→      setState((prev) => ({
   131→        ...prev,
   132→        error:
   133→          error instanceof Error
   134→            ? error.message
   135→            : "Failed to initialize frame capture",
   136→      }));
   137→      throw error;
   138→    }
   139→  }, []);
   140→
   141→  // Start frame capture
   142→  const startCapture = useCallback(
   143→    async (newOptions?: Partial<FrameCaptureOptions>): Promise<void> => {
   144→      if (state.isCapturing) {
   145→        throw new Error("Frame capture already in progress");
   146→      }
   147→
   148→      try {
   149→        // Update options if provided
   150→        if (newOptions) {
   151→          updateOptions(newOptions);
   152→        }
   153→
   154→        await initialize();
   155→
   156→        setState((prev) => ({
   157→          ...prev,
   158→          isCapturing: true,
   159→          error: null,
   160→        }));
   161→
   162→        console.log("Frame capture started");
   163→      } catch (error) {
   164→        console.error("Failed to start frame capture:", error);
   165→        setState((prev) => ({
   166→          ...prev,
   167→          error:
   168→            error instanceof Error
   169→              ? error.message
   170→              : "Unknown error starting frame capture",
   171→        }));
   172→        throw error;
   173→      }
   174→    },
   175→    [state.isCapturing, initialize, updateOptions]
   176→  );
   177→
   178→  // Capture a single frame
   179→  const captureFrame = useCallback(
   180→    async (
   181→      viewRef: any,
   182→      index: number,
   183→      totalFrames: number
   184→    ): Promise<CapturedFrame | null> => {
   185→      console.log(`🔍 useFrameCapture.captureFrame called with:`, {
   186→        index,
   187→        totalFrames,
   188→        isCapturing: state.isCapturing,
   189→        hasViewRef: !!viewRef,
   190→      });
   191→
   192→      if (!state.isCapturing || !state.tempDirectory) {
   193→        console.log("❌ Frame capture conditions not met:", {
   194→          isCapturing: state.isCapturing,
   195→          hasTempDirectory: !!state.tempDirectory,
   196→        });
   197→        return null;
   198→      }
   199→
   200→      try {
   201→        const options = optionsRef.current;
   202→
   203→        // Generate a formatted frame number for sequential naming
   204→        const frameNumber = String(index).padStart(4, "0");
   205→        const fileName = `frame_${frameNumber}.${options.format}`;
   206→        const filePath = `${state.tempDirectory}${fileName}`;
   207→
   208→        console.log(`📁 Saving frame to: ${filePath}`);
   209→
   210→        console.log(
   211→          "📸 Attempting to capture view with react-native-view-shot..."
   212→        );
   213→        const uri = await captureRef(viewRef, {
   214→          format: options.format,
   215→          quality: options.quality,
   216→          result: "data-uri",
   217→          width: options.width,
   218→          height: options.height,
   219→          snapshotContentContainer: false, // Don't use snapshotContentContainer for map views
   220→        });
   221→
   222→        console.log(
   223→          "✅ View captured successfully, URI length:",
   224→          uri?.length || 0
   225→        );
   226→        console.log("📸 Frame data preview:", uri?.substring(0, 50) + "...");
   227→
   228→        // Save the data URI to file
   229→        if (uri.startsWith("data:")) {
   230→          // Extract base64 data from data URI
   231→          const base64Data = uri.split(",")[1];
   232→          console.log("💾 Writing base64 data to file...");
   233→
   234→          await FileSystem.writeAsStringAsync(filePath, base64Data, {
   235→            encoding: FileSystem.EncodingType.Base64,
   236→          });
   237→          console.log("💾 File written successfully");
   238→        } else {
   239→          console.log(
   240→            "⚠️ URI doesn't start with 'data:', URI:",
   241→            uri?.substring(0, 50)
   242→          );
   243→        }
   244→
   245→        const frame: CapturedFrame = {
   246→          uri,
   247→          index,
   248→          timestamp: Date.now(),
   249→        };
   250→
   251→        // Update state with new frame
   252→        setState((prev) => {
   253→          const newCapturedFrames = [...prev.capturedFrames, frame];
   254→          const newProgress = {
   255→            total: totalFrames,
   256→            current: index + 1,
   257→            percentage: (index + 1) / totalFrames,
   258→          };
   259→
   260→          console.log(
   261→            `📊 Frame ${index} added to capturedFrames array, total: ${newCapturedFrames.length}`
   262→          );
   263→          console.log(`📄 Frame ${index} metadata:`, {
   264→            index: frame.index,
   265→            timestamp: frame.timestamp,
   266→            uriLength: frame.uri?.length || 0,
   267→          });
   268→
   269→          // Report progress via callback if provided
   270→          if (onProgressCallbackRef.current) {
   271→            onProgressCallbackRef.current(newProgress);
   272→          }
   273→
   274→          return {
   275→            ...prev,
   276→            capturedFrames: newCapturedFrames,
   277→            progress: newProgress,
   278→          };
   279→        });
   280→
   281→        console.log(`✅ Frame ${index} captured and processed successfully`);
   282→        return frame;
   283→      } catch (error) {
   284→        console.error(`❌ Failed to capture frame ${index}:`, error);
   285→        setState((prev) => ({
   286→          ...prev,
   287→          error:
   288→            error instanceof Error
   289→              ? error.message
   290→              : "Unknown error during frame capture",
   291→        }));
   292→        return null;
   293→      }
   294→    },
   295→    [state.isCapturing, state.tempDirectory]
   296→  );
   297→
   298→  // Stop frame capture
   299→  const stopCapture = useCallback(async (): Promise<CapturedFrame[]> => {
   300→    if (!state.isCapturing) {
   301→      return [];
   302→    }
   303→
   304→    setState((prev) => ({
   305→      ...prev,
   306→      isCapturing: false,
   307→    }));
   308→
   309→    console.log(
   310→      `Frame capture completed. Captured ${state.capturedFrames.length} frames`
   311→    );
   312→
   313→    return [...state.capturedFrames];
   314→  }, [state.isCapturing, state.capturedFrames.length]);
   315→
   316→  // Cleanup frames
   317→  const cleanupFrames = useCallback(async (): Promise<void> => {
   318→    try {
   319→      if (state.tempDirectory) {
   320→        await FileSystem.deleteAsync(state.tempDirectory, { idempotent: true });
   321→      }
   322→
   323→      setState((prev) => ({
   324→        ...prev,
   325→        capturedFrames: [],
   326→        tempDirectory: null,
   327→      }));
   328→
   329→      console.log("Cleaned up temporary frame files");
   330→    } catch (error) {
   331→      console.warn("Frame cleanup failed:", error);
   332→      setState((prev) => ({
   333→        ...prev,
   334→        error: error instanceof Error ? error.message : "Frame cleanup failed",
   335→      }));
   336→    }
   337→  }, [state.tempDirectory]);
   338→
   339→  // Get frame files info
   340→  const getFrameFilesInfo = useCallback((): {
   341→    count: number;
   342→    directory: string;
   343→    isCapturing: boolean;
   344→  } => {
   345→    return {
   346→      count: state.capturedFrames.length,
   347→      directory: state.tempDirectory || "",
   348→      isCapturing: state.isCapturing,
   349→    };
   350→  }, [state.capturedFrames.length, state.tempDirectory, state.isCapturing]);
   351→
   352→  // Export frame directory
   353→  const exportFrameDirectory = useCallback(async (): Promise<string | null> => {
   354→    if (!state.tempDirectory || state.capturedFrames.length === 0) {
   355→      return null;
   356→    }
   357→
   358→    try {
