   380→      console.error("Failed to export frame directory:", error);
   381→      setState((prev) => ({
   382→        ...prev,
   383→        error:
   384→          error instanceof Error
   385→            ? error.message
   386→            : "Failed to export frame directory",
   387→      }));
   388→      return null;
   389→    }
   390→  }, [state.tempDirectory, state.capturedFrames]);
   391→
   392→  return {
   393→    // State
   394→    ...state,
   395→
   396→    // Actions
   397→    startCapture,
   398→    captureFrame,
   399→    stopCapture,
   400→    cleanupFrames,
   401→    exportFrameDirectory,
   402→    getFrameFilesInfo,
   403→
   404→    // Additional utilities
   405→    setProgressCallback,
   406→    updateOptions,
   407→  };
   408→};
